fun interfaceTranslation(text:String,language:String):String? {
    val row=interfaceRows[text] ?: interfaceRows2[text] ?: rightsRows[text] ?: notioRows[text] ?: syncPortRows[text] ?: return null
    if(language=="ru")return text
    val index=interfaceLanguages.indexOf(language)
    return row[if(index<0)0 else index]
}
